// Checks the files generated by the pipeline (public/parks/<key>/) against
// their formats. Parks without generated data are skipped.
import fs from 'node:fs';
import path from 'node:path';
import { describe, expect, it } from 'vitest';
import { PARKS } from '#parks/index.js';
import { groundTileId, groundTilePath, groundTileRect } from '#shared/formats/ground-tiles.js';
import { makeDesignArea } from '#shared/design-area.js';
import { PAVING_FILE, PAVING_SIZE } from '#shared/formats/paving.js';

const parks = Object.keys(PARKS).filter((key) => fs.existsSync(`public/parks/${key}/park.json`));

describe.each(parks)('generated data of %s', (key) => {
  const dir = path.join('public/parks', key);
  const park = JSON.parse(fs.readFileSync(path.join(dir, 'park.json'), 'utf8'));

  it('lists ground tiles that exist, including the overview', () => {
    expect(park.ground.tiles).toContain(groundTileId(0, 0, 0));
    for (const id of park.ground.tiles) expect(fs.existsSync(path.join(dir, groundTilePath(id))), id).toBe(true);
  });

  it('has a designed area inside the extent', () => {
    const area = makeDesignArea(park.clear);
    expect(park.clear.radii.length).toBeGreaterThan(8);
    expect(area.coversRect(...groundTileRect(park.extent, 0, 0, 0))).toBe(false);
    expect(area.contains(park.clear.cx, park.clear.cz)).toBe(true);
  });

  it('has a paving mask of the expected size (mobile export)', () => {
    const png = fs.readFileSync(path.join(dir, PAVING_FILE));
    expect(png.readUInt32BE(16)).toBe(PAVING_SIZE);
    expect(png.readUInt32BE(20)).toBe(PAVING_SIZE);
  });

  it('places activities inside the extent', () => {
    const { cx, cz, size } = park.extent;
    for (const p of park.pois) {
      expect(Math.abs(p.x - cx)).toBeLessThan(size);
      expect(Math.abs(p.z - cz)).toBeLessThan(size);
    }
  });
});
